@startuml

class Bettor {
  + name : string
  + id : string
}

class Race {
  + raceId : string
  + description : string
}

class Runner {
  + horseName : string
  + runnerId : string
}

class Jockey {
  + name : string
  + licenseNumber : string
}

class Bet {
  + amount : double
  + odds : double
}

class Bookmaker {
  + name : string
  + calculateTotalWinnings() : double
  + calculateTotalLosses() : double
}

Bettor "1" -- "*" Bet
Race "1" *-- "1..*" Runner
Runner "1" -- "1" Jockey
Bet "*" -- "1" Race
Bet "*" -- "1" Runner
Bookmaker "1" -- "*" Bet

@enduml

